ST.xhtml:p:
RTrigger_Layerstart(CLK := g_bLayerStartM);
RTrigger_Layerend(CLK := g_bLayerEndM);
RTrigger_Corner_in(CLK := g_bLaserOnCornerM OR g_biLaserOnCorner);
RTrigger_Corner_out(CLK := g_bLaserOutCornerM OR g_biLaserOutCorner);
RTrigger_FirstGas(CLK := g_bStartRunOpenGasM);
RTrigger_UpLift(CLK := g_biLayerEndUplift OR g_bLayerEndUpliftM);
RTriggerClaw3UpLift(CLK := g_biClaw3UpLift OR g_bClaw3UpLiftM);
RTriggerProfileStart(CLK := g_bProfileStartM);(*从这里进来，说明该轮廓是板外切割profile_start*)
RTriggerProfileLaserGasStart(CLK := g_bProfileLaserGasM);
RTrigger_ProcessEnd(CLK := g_bPlcEndM OR g_bProcessEndM);
RTrigger_LayerstartOffLaser(CLK := g_bLayerStartOffLaserM);(*从这里进来，说明需要开随动而不开光 *)

nToolNum := g_nToolNum;

(*输出拐角速度*)
g_doCornerSpeed := g_TechData.multilTechData[nToolNum-1].CornerCompen.dSpeed;
(*输出进/出拐角冷却时间*)
g_dCutHeight := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height;
(*将切割高度传给CNC,不切割状态默认传第一把刀具的切割高度*)
g_doCutHeightToCNC := g_dCutHeight;
IF g_nPlcState = 0 THEN
  g_doCutHeightToCNC := g_TechData.multilTechData[0].DIRECUT_CUTTING.fCutting_Height;
END_IF;

g_foInCornerCoolTime := DINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].CornerCompen.nInCornerCloseLaserTime)/1000.0;
g_foOutCornerCoolTime := DINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].CornerCompen.nOutCornerCloseLaserTime)/1000.0;
(*关气延时到了，就关气，如果在这个过程中又来了开气的指令，则忽略关气*)
(*在Layer end中已经实现了关气，所以不需要再在LayerStart中处理bCloseGasDelayEnable*)
(*但是为了安全起见，还是在Layerstart里面对bCloseGasDelayEnable置false*)
IF RTrigger_Layerstart.Q THEN
  bCloseGasDelayEnable := FALSE;
END_IF;
TON_CloseGasDelay(IN := bCloseGasDelayEnable, PT := LREAL_TO_TIME(FUN_MStoS(nCloseGasDelayTime)));
IF TON_CloseGasDelay.Q THEN
      g_bgas_enable := FALSE;(*关闭气阀的数字量输出*)
      bCloseGasDelayEnable := FALSE;
END_IF;
IF g_nOpenGasDelayTime<5 THEN(*开气延时最小5ms，保证气比光先出5ms*)
  g_nOpenGasDelayTime := 5;
END_IF;

IF RTrigger_FirstGas.Q THEN
  g_bFirstGas := TRUE;
  g_bStartRunOpenGasM := FALSE;
END_IF;

g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
IF RTrigger_Layerstart.Q THEN
  g_bLayerStartM := FALSE;
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerStartState := 500;
    bLookBackDone := FALSE;
  ELSE
    nLayerStartState := 9;
  END_IF;
  nLayerEndState := 0;
  TON_PauseStopLaserDelay(IN :=FALSE);(*暂停关光延时*)
  g_bProfileEnable := FALSE;
  g_bProfileLaserEnable := FALSE;
  (*bUpLiftFlag := FALSE;
  bClaw3UpLiftFlag := FALSE;*)
END_IF;

(*板外切割-随动定高：随动定高后上抬*)
IF RTriggerProfileStart.Q THEN
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerStartState := 501;
    bLookBackDone := FALSE;
  ELSE
    nLayerStartState := 9;
  END_IF;
  nLayerEndState := 0;
  g_dProfileCuttingPos := 0.0;(*板外切割时，随动下来记录的坐标，用于暂停后开始寸动下来时使用*)
  TON_PauseStopLaserDelay(IN :=FALSE);(*暂停关光延时*)
  g_bProfileEnable := TRUE;
  g_bProfileFollowEnable := FALSE;(*板外切割开随动标志位清零*)
  g_bProfileStartM := FALSE;
END_IF;
(*板外切割开始触发，跳过穿孔、随动，直接定高开始出气、出光切割*)
IF RTriggerProfileLaserGasStart.Q THEN
  g_bProfileLaserGasM  := FALSE;
  g_bProfileLaserEnable := TRUE;

  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerStartState := 500;
    bLookBackDone := FALSE;
  ELSE
    g_boCNCMoveDisable := TRUE;
    nLayerStartState := 400;
  END_IF;
  nLayerEndState := 0;
END_IF;

IF RTrigger_Layerend.Q THEN
  g_bLayerEndM := FALSE;
  g_bLayerStartOffLaser:= FALSE;(*开随动不开关状态标志位*)
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerEndState := 600;
  ELSE
    nLayerEndState := 10;
  END_IF;
  nLayerStartState := 0;
  g_boLayerEndDone := FALSE;
  bClaw3UpLiftFlag := FALSE;
  bUpLiftFlag := FALSE;
  g_bProfileEnable := FALSE;
  g_bProfileLaserEnable := FALSE;
  g_bProfileFollowEnable := FALSE;(*板外切割开随动标志位清零*)
END_IF;

IF RTrigger_UpLift.Q THEN
  bUpLiftFlag := TRUE;
  g_bLayerEndUpliftM  := FALSE;
END_IF;

IF RTriggerClaw3UpLift.Q THEN
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    bClaw3UpLiftFlag := FALSE;
    g_boClaw3UpLiftDone := TRUE;
  ELSE
    bClaw3UpLiftFlag := TRUE;
    g_boClaw3UpLiftDone := FALSE;    
  END_IF;
  g_bClaw3UpLiftM := FALSE;  
END_IF;

IF RTrigger_ProcessEnd.Q THEN
  nLayerStartState := 0;
  nLayerEndState := 0;
  g_bProcessEndM := FALSE;
END_IF;

IF RTrigger_LayerstartOffLaser.Q THEN
  g_bLayerStartOffLaserM := FALSE;
  g_bLayerStartOffLaser:= TRUE;(*开随动不开关状态标志位*)
  IF g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb THEN
    nLayerStartState := 500;
    bLookBackDone := FALSE;
  ELSE
    nLayerStartState := 9;
  END_IF;
  nLayerEndState := 0;
  TON_PauseStopLaserDelay(IN :=FALSE);(*暂停关光延时*)
  g_bProfileEnable := FALSE;
  g_bProfileLaserEnable := FALSE;
  (*bUpLiftFlag := FALSE;
  bClaw3UpLiftFlag := FALSE;*)
END_IF;


CASE nLayerStartState OF
  0:(*空闲*)
    nLayerStartState := 0;
    nLayerStartState_bak := 0;
  9:(*关闭CNC运动使能*)
    nLayerStartState_bak := 9;
    g_boCNCMoveDisable := TRUE;
    g_nCurCutState :=0;
    bZHeightJudgeOpen := TRUE;
    nLayerStartState := 10;
    IF g_bProfileEnable THEN
      nLayerStartState := 20;
    END_IF;
    IF bLookBackDone THEN
      bLookBackDone := FALSE;
      IF g_niMotionType > 1 THEN
        nLayerStartState := 400;
      END_IF;
    END_IF;
  10:
    nLayerStartState_bak := 10; 
    g_bZFollowClose := TRUE;
    IF g_bZFollowOutDone THEN
      nLayerStartState := 11;
      g_bZFollowClose := FALSE;
    END_IF;
    g_nFrogLeapOpenGasTime := LREAL_TO_DINT(TIME_TO_LREAL(TON_FrogLeapOpenGas.ET)*1000.0); (*蛙跳到此时已出气时间ms*)
    IF g_nFrogLeapOpenGasTime >= g_nOpenGasDelayTime THEN
      g_nOpenGasDelayTimeAdd := 0;      (*蛙跳出气时间>=开气延时时间，就不需开气延时，否则开气延时时间要减去蛙跳出气时间*)
    ELSE
      g_nOpenGasDelayTimeAdd := ABS(g_nOpenGasDelayTime - g_nFrogLeapOpenGasTime);
    END_IF;
    TON_FrogLeapOpenGas(In := FALSE);
  11:(*穿孔*)
    nLayerStartState_bak := 11;
    g_nPiercingStatus := 1;
    IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN
      nLayerStartState := 20;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=1 THEN
      nLayerStartState := 100;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=2 THEN
      nLayerStartState := 200;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=3 THEN
      nLayerStartState := 300;
    END_IF;
    IF g_bLayerStartOffLaser THEN(*不开光切割，穿孔就跳过了*)
      nLayerStartState := 20;
    END_IF;
  20:(*直接切割*)
    nLayerStartState_bak := 20;
    IF g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height <= g_dZFollowMaxHeight THEN (*直接切割高度小于随动最大高度，直接到切割高度*)  
      nLayerStartState := 400;
      IF g_bProfileEnable THEN
        nLayerStartState := 50;
      END_IF;
    ELSE  
     nLayerStartState := 25;
    END_IF;
  25:(*随动到1.0mm*)  
    nLayerStartState_bak := 25;
    g_fZFollowHeight := 1.0;
    g_bZFollowExecute := TRUE;
    g_bFocusDone := FALSE;
    g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Focus;
    g_bFocusEnable := TRUE;(*通知F *) 
    nLayerStartState := 30;
  30:(*等待随动到位，并关随动*)     
    nLayerStartState_bak := 30; 
    IF g_bZFollowDone THEN 
      g_bZFollowExecute := FALSE;
      g_bZFollowClose := TRUE;
      nLayerStartState := 35;
      bZHeightJudgeOpen := FALSE;
    END_IF; 
  35: (*等待关随动到位*)  
    nLayerStartState_bak := 35;
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
     nLayerStartState := 40;
    END_IF; 
  40: (*上抬到切割高度，并出光出气*)  
    nLayerStartState_bak := 40;
    g_fZRelDistance := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height - 1.0;
    g_bZRelExecute := TRUE; 
    IF g_bProfileEnable THEN(*板外切割：不出光不出气*)
      nLayerStartState := 45;
    ELSE(*出气*)
      g_ugas_type := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
      g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dair_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
      g_bgas_enable := TRUE; 
      IF g_bFirstGas THEN
        IF g_bChangeGasFlag THEN 
          nTimeTemp := g_nFirstGasDelayTime + g_nChangeGasDelayTime;
        ELSE
          nTimeTemp := g_nFirstGasDelayTime;
        END_IF;
      ELSE
        IF g_bChangeGasFlag THEN 
          nTimeTemp := g_nChangeGasDelayTime;
        ELSE
          nTimeTemp := 0;
        END_IF;
      END_IF;
      IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN
        nTimeTemp := nTimeTemp + g_nOpenGasDelayTimeAdd;
      END_IF;
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTimeTemp)));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        nLayerStartState := 45;
      END_IF;
    END_IF;

  45: (*上抬完成*)
    nLayerStartState_bak := 45;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerStartState := 50;
    END_IF;
    g_nPiercingStatus := 0;
    g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
  50: (*随动到切割高度*)
    nLayerStartState_bak := 50;
    g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height;
    g_bZFollowExecute := TRUE;
    IF g_bProfileEnable THEN
      nLayerStartState := 55;
    ELSE
      nLayerStartState := 420;
    END_IF;

  55:(*等待切割随动到位*)(*板外切割：记录要定高的坐标，并且上抬*)
    nLayerStartState_bak := 55; 
    IF g_bZFollowDone THEN
      g_bZFollowExecute := FALSE;
      g_dProfileCuttingPos := Axis_Z.NCTOPLC.SETPOS;
      nLayerStartState := 60;
      bZHeightJudgeOpen := FALSE;
    END_IF;
  60:(*板外切割：关随动*)
    nLayerStartState_bak := 55;
    g_bZFollowExecute := FALSE;
    g_bZFollowClose := TRUE;
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
      nLayerStartState := 65;
      (*根据不同管型，获取△上抬距离（安全距离） pipetype: 0、平面 1、圆 2、矩形 3、腰 4、椭圆 5、D型管 10、H钢 11、角钢*)
      dXCoordToCenter := ABS(g_diXMachineCoordinate - g_dBeamCenterPos);(*X轴当前坐标距离X轴中心的距离*)
      IF g_nPipeType = 1 THEN 
        IF dXCoordToCenter >= 0.5 THEN(*判断是平面孔情况的还是空间孔情况*) 
           (*如果轮廓跳转时检测到X轴不在中心位置，需要上抬保证安全*)
           dCircleLiftTemp := SQRT(g_dCircleRadius*g_dCircleRadius - dXCoordToCenter*dXCoordToCenter);
           dMaxChangeHeight := g_dCircleRadius - dCircleLiftTemp + 1.0;
        ELSE
          dMaxChangeHeight := 0.0; 
        END_IF;
      ELSIF g_nPipeType = 2 OR g_nPipeType = 11 THEN
        dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) - MIN(g_dSquareLenght,g_dSquareWidth)/2.0 + 10.0;
      ELSIF g_nPipeType = 3 OR g_nPipeType = 4 THEN  
        dMaxChangeHeight := (g_dSquareLenght-g_dSquareWidth)/2.0 + 5.0;
      ELSIF g_nPipeType = 10 THEN
        dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) + 10.0;
      ELSE 
        dMaxChangeHeight := 0.0;
      END_IF;
    END_IF;

  65:(*上抬*)
    nLayerStartState_bak := 65;
    (*dUpLiftheight:轮廓间上抬高度  dMaxChangeHeight：△上抬距离（安全距离）*)
    IF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight + dMaxChangeHeight) <= g_fLiftCoord THEN
      g_fZRelDistance := dUpLiftheight + dMaxChangeHeight;
    ELSIF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight + dMaxChangeHeight) > g_fLiftCoord AND (Axis_Z.NCTOPLC.ACTPOS + dMaxChangeHeight) < g_fLiftCoord THEN
      g_fZRelDistance := g_fLiftCoord - Axis_Z.NCTOPLC.ACTPOS;
    ELSIF (Axis_Z.NCTOPLC.ACTPOS + dMaxChangeHeight) >= g_fLiftCoord THEN
      g_fZRelDistance := dMaxChangeHeight;
    END_IF;  

    g_bZRelExecute := TRUE;

    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerStartState := 70;
    END_IF;
  70:(*开启CNC运动使能*)
    nLayerStartState_bak := 70; 
    g_boCNCMoveDisable := FALSE;
    nLayerStartState := 501;  


  100:(*普通穿孔出气变焦及随动*)
    nLayerStartState_bak := 100;
    IF g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height <= g_dZFollowMaxHeight THEN (*普通穿孔高度<随动最高高度,直接随动到位*)
      g_ugas_type := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.nNormal_Piercing_Gas;
      g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;
      g_dair_pressure := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;
      g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;
      g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;
      g_bgas_enable := TRUE;

      g_fZFollowHeight := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height;
      g_bZFollowExecute := TRUE;

      nLayerStartState := 101;  
    ELSE
      g_fZFollowHeight := 1.0;
      g_bZFollowExecute := TRUE;

      nLayerStartState := 102;  
    END_IF;  
    g_bFocusDone := FALSE;
    g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.fNormal_Zoom_Position;   
    g_bFocusEnable := TRUE;(*通知F轴调焦*) 

  101:(*等待普通穿孔出气延时完成*)
    nLayerStartState_bak := 101;
    IF g_bFirstGas THEN(*首吹气延时:*)
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(MAX(g_nFirstGasDelayTime,g_nOpenGasDelayTimeAdd))));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        g_bFirstGas := FALSE;
        nLayerStartState := 102;
      END_IF;
    ELSE
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nOpenGasDelayTimeAdd)));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        nLayerStartState := 102;
      END_IF;
    END_IF; 

  102:(*等待普通穿孔随动到位完成*)
    nLayerStartState_bak := 102; 
    IF g_bZFollowDone THEN
      TON_FirstGasDelay(IN := FALSE); 
      g_bZFollowExecute := FALSE;
      g_bZFollowClose := TRUE;
      nLayerStartState := 103;
      bZHeightJudgeOpen := FALSE;
    END_IF; 
  103:(*等待普通穿孔关随动完成*)
    nLayerStartState_bak := 103;
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
      IF g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height <= g_dZFollowMaxHeight THEN
        nLayerStartState := 120;
      ELSE
        nLayerStartState := 104;
      END_IF;
    END_IF;
  104: (*探底后移动到普通穿孔高度，出气变焦*)
    nLayerStartState_bak := 104;
    g_fZRelDistance := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height - 1.0;
    g_bZRelExecute := TRUE;
    g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.nNormal_Piercing_Gas;
    g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;
    g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;
    g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;
    g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;
    g_bgas_enable := TRUE;

    IF g_bFirstGas THEN(*首吹气延时:*)
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(MAX(g_nFirstGasDelayTime,g_nOpenGasDelayTimeAdd))));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        g_bFirstGas := FALSE;
        nLayerStartState := 105;
      END_IF;
    ELSE
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nOpenGasDelayTimeAdd)));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        nLayerStartState := 105;
      END_IF;
    END_IF;  

  105:(*等待运动到普通穿孔*)
    nLayerStartState_bak := 105;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerStartState := 120;
    END_IF;

  120:(*普通穿孔出光*)
    nLayerStartState_bak := 120;
    g_bFirstGas := FALSE; (*复位首点吹气标志位*)
    IF g_bFocusDone THEN (*调焦完成*)
      g_nPower := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.nNormal_Piercing_Power;
      g_nPwmFreq := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.nNormal_Piercing_Frequency;
      g_nPwmDuty := g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.nNormal_Piercing_Duty;
      g_bLaserCuttingEnable := TRUE;
      TON_NormalPiercingTime(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.nNormal_Piercing_Time)));
      IF TON_NormalPiercingTime.Q THEN
        nLayerStartState := 130;
        TON_NormalPiercingTime(IN := FALSE);
      END_IF;
    END_IF;
  130:(*普通穿孔关光*)
    nLayerStartState_bak := 130;
    g_bLaserCuttingEnable := FALSE;
    nLayerStartState := 140;
  140:(*普通穿孔关气*)
    nLayerStartState_bak := 140;
    IF (g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.nNormal_Piercing_Gas<>g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas) AND (nToolNum-1)<>6 THEN
      g_bChangeGasFlag := TRUE; 
    END_IF;
    IF g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.bNormal_StopLight_BlowGas THEN
       nLayerStartState := 145;
    ELSE
       nLayerStartState := 400;
    END_IF;
  145:(*普通穿孔--停光吹气延时*)
    nLayerStartState_bak := 145;
    TON_StopLightBlow(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].NORMAL_CUTTING.nNormal_StopLight_BlowGasTime)));
    IF TON_StopLightBlow.Q THEN
      TON_StopLightBlow(IN := FALSE); 
     nLayerStartState := 390;
    END_IF;
  200:(*渐进穿孔*)
    nLayerStartState_bak := 200; 
    (*是否开启爆孔*)
    IF g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.bBurstingHole_Enable THEN
      IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height <= g_dZFollowMaxHeight THEN (*爆孔高度<随动最高高度,直接随动到爆孔位置*)
        (*通知随动:爆孔位置*)
        g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height;
        g_bZFollowExecute := TRUE;
        (*通知吹气:爆孔*)
        g_ugas_type := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_gas;
        g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;
        g_dair_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;
        g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;
        g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;
        g_bgas_enable := TRUE;
        IF g_bFirstGas THEN(*首吹气延时:*)
          TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(MAX(g_nFirstGasDelayTime,g_nOpenGasDelayTimeAdd))));
          IF TON_FirstGasDelay.Q THEN
            TON_FirstGasDelay(IN :=FALSE);
            g_bFirstGas := FALSE;
            nLayerStartState := 201;
          END_IF;
        ELSE
          TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nOpenGasDelayTimeAdd)));
          IF TON_FirstGasDelay.Q THEN
            TON_FirstGasDelay(IN :=FALSE); 
            nLayerStartState := 201;
          END_IF;
        END_IF; 
      ELSE
        (*通知随动:1MM*)
        g_fZFollowHeight := 1.0;
        g_bZFollowExecute := TRUE;
        nLayerStartState := 201;
      END_IF;  
      (*通知F轴调焦:爆孔*)
      g_bFocusDone := FALSE;
      g_dZoomPosition := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_zoom_position;
      g_bFocusEnable := TRUE;

    ELSE(* 不爆孔*)
      IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Height <= g_dZFollowMaxHeight THEN (*渐进穿孔高度<随动最高高度，直接穿孔到位*)
        (*通知随动:渐进穿孔高度*)
        g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Height;
        g_bZFollowExecute := TRUE;
        (*通知吹气:渐进穿孔 *)
        g_ugas_type := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Gas;
        g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
        g_dair_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
        g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
        g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
        g_bgas_enable := TRUE;
        IF g_bFirstGas THEN(*首吹气延时:*)
          TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(MAX(g_nFirstGasDelayTime,g_nOpenGasDelayTimeAdd))));
          IF TON_FirstGasDelay.Q THEN
            TON_FirstGasDelay(IN :=FALSE);
            g_bFirstGas := FALSE;
            nLayerStartState := 201;
          END_IF;
        ELSE
          TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nOpenGasDelayTimeAdd)));
          IF TON_FirstGasDelay.Q THEN
            TON_FirstGasDelay(IN :=FALSE); 
            nLayerStartState := 201;
          END_IF;
        END_IF; 
      ELSE
        (*通知随动:1mm*)
        g_fZFollowHeight := 1.0;
        g_bZFollowExecute := TRUE;
        nLayerStartState := 201;
      END_IF; 
      (*通知F轴调焦:渐进穿孔*)
      g_bFocusDone := FALSE;
      g_dZoomPosition := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fStart_Zoom_Position; (*Z轴上抬变焦坐标*)
      g_bFocusEnable := TRUE;
    END_IF;     
  201:(*等待随动完成*)
    nLayerStartState_bak := 201;
    IF g_bZFollowDone THEN
      g_bZFollowExecute := FALSE; 
      g_bZFollowClose := TRUE;
      nLayerStartState := 202;
      bZHeightJudgeOpen := FALSE;
    END_IF;
  202:(*等待关随动完成*)
    nLayerStartState_bak := 202;  
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
      nLayerStartState := 203;
    END_IF;
  203:
    nLayerStartState_bak := 203;
    (*是否开启爆孔*)
    IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.bBurstingHole_Enable THEN 
      IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height <= g_dZFollowMaxHeight THEN (*爆孔高度<随动最高高度,直接随动到爆孔位置*)
         nLayerStartState := 230;
      ELSE
        nLayerStartState := 205;
      END_IF;
    ELSE
      (*不爆孔*)
      IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Height <= g_dZFollowMaxHeight THEN
        nLayerStartState := 265;
      ELSE
        nLayerStartState := 205;
      END_IF; 
    END_IF;   

  205:
    nLayerStartState_bak := 205;  
      IF g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.bBurstingHole_Enable THEN
        nLayerStartState := 210; 
      ELSE
        nLayerStartState := 250;
      END_IF; 
    (*dProgressZoomTime := 0.0;*)
    (*dProgressZoomDiff := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fEnd_Zoom_Position - g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fStart_Zoom_Position; *)
  210:(*爆孔*)
    nLayerStartState_bak := 210;
    (*通知上抬:渐进穿孔高度*)
    g_fZRelDistance := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height - 1.0;
    g_bZRelExecute := TRUE; 
    (*通知吹气:爆孔*)
    g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_gas;
    g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;
    g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;
    g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;
    g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;
    g_bgas_enable := TRUE;
    IF g_bFirstGas THEN(*首吹气延时:*)
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(MAX(g_nFirstGasDelayTime,g_nOpenGasDelayTimeAdd))));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        g_bFirstGas := FALSE;
        nLayerStartState := 220;
      END_IF;
    ELSE
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nOpenGasDelayTimeAdd)));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE); 
        nLayerStartState := 220;
      END_IF;
    END_IF;     
  220:(*等待爆孔位完成*)
    nLayerStartState_bak := 220;
    g_bFirstGas := FALSE;  (*首吹气标志位复位*)
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerStartState := 230;
    END_IF;

  230:(*出光*)
    nLayerStartState_bak := 230;
    IF g_bFocusDone THEN
      g_nPower := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Power;
      g_nPwmFreq := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Frequency;
      g_nPwmDuty := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Duty;
      g_bLaserCuttingEnable := TRUE;
      TON_BurstingTime(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fBurstingHole_Time)));
      IF TON_BurstingTime.Q THEN
        TON_BurstingTime(IN := FALSE);
        nLayerStartState := 235;
      END_IF;
    END_IF;
  235:(*关光*)
    nLayerStartState_bak := 235;
    g_bLaserCuttingEnable := FALSE;
    nLayerStartState := 238;
  238:(*关气*)
    nLayerStartState_bak := 238;
    IF g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Gas<>g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_gas THEN
      g_bChangeGasFlag := TRUE;
    END_IF;
    IF g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.bBurstingHole_open_gas THEN
       nLayerStartState := 239;
    ELSE
       nLayerStartState := 240;
    END_IF;
  239:(*爆孔-停光吹气延时*)
    nLayerStartState_bak := 239;
    TON_StopLightBlow(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_open_gas_time)));
    IF TON_StopLightBlow.Q THEN
      TON_StopLightBlow(IN := FALSE);
      nLayerStartState := 240;
    END_IF;
  240:(*去渐进位*)
    nLayerStartState_bak := 240;
    g_fZRelDistance := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Height - g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height;
    g_bZRelExecute := TRUE;
    g_ugas_type := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Gas;
    g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
    g_dair_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
    g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
    g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
    g_bgas_enable := TRUE; 
    nLayerStartState := 260;
    g_bFocusDone := FALSE;
    g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fStart_Zoom_Position;   
    g_bFocusEnable := TRUE;(*通知F轴调焦*)
  250:(*去渐进位*)
    nLayerStartState_bak := 250;
    TON_FirstGasDelay(IN := TRUE);
    g_fZRelDistance := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Height - 1.0;
    g_bZRelExecute := TRUE;

    g_bFocusDone := FALSE;
    g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fStart_Zoom_Position;   
    g_bFocusEnable := TRUE;(*通知F轴调焦*)

    g_ugas_type := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Gas;
    g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
    g_dair_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
    g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
    g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;
    g_bgas_enable := TRUE;
    IF g_bFirstGas THEN(*首吹气延时:*)
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(MAX(g_nFirstGasDelayTime,g_nOpenGasDelayTimeAdd))));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        g_bFirstGas := FALSE;
        nLayerStartState := 260;
      END_IF;
    ELSE
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nOpenGasDelayTimeAdd)));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE); 
        nLayerStartState := 260;
      END_IF;
    END_IF; 
  260:(*渐进等待到渐进位完成*)
    nLayerStartState_bak := 260;
    g_bFirstGas := FALSE;  (*首吹气标志位复位*)
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE; 
      nLayerStartState := 265;
    END_IF;
  265:(*渐进出光*)
    nLayerStartState_bak := 265;
    IF g_bFocusDone THEN
      g_nPower := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Power;
      g_nPwmFreq := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Frequency;
      g_nPwmDuty := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Duty;
      g_bLaserCuttingEnable := TRUE;
      nLayerStartState := 270;
    END_IF;
  270:
    nLayerStartState_bak := 270;
    g_fZRelDistance := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height - g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Height;
    (*fixme需要给定速度*)
    g_fZRelVelocity := ABS(g_fZRelDistance/FUN_MStoS(g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Time));
    g_bZRelExecute := TRUE;
    dProgressZoomTime := 0.0;  (*变焦时间清零，变焦寸动距离*)
    dProgressZoomDiff := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fEnd_Zoom_Position - g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fStart_Zoom_Position;
    nLayerStartState := 272;
  272:
    nLayerStartState_bak := 272;
    IF g_nFAxisControl = 2 THEN (*轴控变焦*)  (*0 :关闭 1 ：F050  2 轴控制 3: 普雷斯特 4 : BM11X *)
       g_bFocusDone := FALSE;
      g_dZoomPosition := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fEnd_Zoom_Position;
      fFAbsDistance := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fEnd_Zoom_Position - g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fStart_Zoom_Position;
      g_dFProgressFocusVel := ABS(fFAbsDistance /FUN_MSTOS(g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Time));
      g_bFProgressFocusAbs := TRUE;
      g_bFocusEnable := TRUE;
      nLayerStartState := 273;  (*轴控调焦使能不能一直给，会导致下次上升沿不触发，所以跳到273*)
    ELSIF g_nFAxisControlType <> 0 THEN(*模拟量变焦*)  (*0 :关闭 1 ：F050  2 轴控制 3: 普雷斯特 4 : BM11X *)
       IF dProgressZoomTime <= DINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Time) THEN
        dProgressZoomTime := dProgressZoomTime + 1.0;
        g_bFocusDone := FALSE;
        g_dZoomPosition := g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.fStart_Zoom_Position + dProgressZoomTime*dProgressZoomDiff/DINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Time);
        g_bFocusEnable := TRUE;(*通知F轴调焦*)
      END_IF;
    END_IF; 

    IF g_fZAxisHeight <= g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height THEN
      g_ZMoveStop.EXECUTE := TRUE;
      g_bZRelExecute := FALSE;
      g_fZRelVelocity := 0.0;
      nLayerStartState := 275;
    ELSIF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      g_fZRelVelocity := 0.0;
      nLayerStartState := 280;
    END_IF; 
  273:
    nLayerStartState_bak := 273;
    IF g_fZAxisHeight <= g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height THEN
      g_ZMoveStop.EXECUTE := TRUE;
      g_bZRelExecute := FALSE;
      g_fZRelVelocity := 0.0;
      nLayerStartState := 275;
    ELSIF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      g_fZRelVelocity := 0.0;
      nLayerStartState := 280;
    END_IF;
  275:
    nLayerStartState_bak := 275;
    IF g_ZMoveStop.Done THEN
      g_ZMoveStop.EXECUTE := FALSE;
      nLayerStartState := 280;
    END_IF;
  280:(*渐进关光*)
    nLayerStartState_bak := 280;
    g_bLaserCuttingEnable := FALSE;
    nLayerStartState := 285;
  285:(*渐进关气*)
    nLayerStartState_bak := 285;
    IF (g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Gas<>g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas) AND (nToolNum-1)<>6 THEN
      g_bChangeGasFlag := TRUE;
    END_IF;
    IF g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.bMove_Piercing_Open_Gas THEN
      nLayerStartState := 288;
    ELSE
      nLayerStartState := 290;
    END_IF;    
  288:(*渐进--停光吹气*)
    nLayerStartState_bak := 288;
    TON_StopLightBlow(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Open_Gas_time)));
    IF TON_StopLightBlow.Q THEN
      TON_StopLightBlow(IN := FALSE);
    nLayerStartState := 290;
    END_IF;   
  290:(*防止渐进变焦还没结束，切割调焦命令就开始，导致不能切割变焦*)
    nLayerStartState_bak := 290;
    IF g_bFocusDone THEN 
      nLayerStartState := 390;
    END_IF; 


  300:(*多级穿孔*)
    nLayerStartState_bak := 300; 
    IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.bPierEnable THEN
      nLayerStartState := 314;
    ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.bPierEnable THEN
      nLayerStartState := 334;
    ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.bPierEnable THEN
      nLayerStartState := 365;
    END_IF;  
  304:(*多级穿孔，随动到1mm，调焦*)
    nLayerStartState_bak := 304;
    g_fZFollowHeight := 1.0;
    g_bZFollowExecute := TRUE;
    IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.bPierEnable THEN
      g_dZoomPosition := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.zoom_FoucsPosition;
    ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.bPierEnable THEN
      g_dZoomPosition := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.zoom_FoucsPosition;
    ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.bPierEnable THEN
      g_dZoomPosition := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.zoom_FoucsPosition;
    END_IF; 
    g_bFocusDone := FALSE;
    g_bFocusEnable := TRUE;  
    IF g_bZFollowDone THEN
      nLayerStartState := 305;
      g_bZFollowExecute := FALSE;
      bZHeightJudgeOpen := FALSE;
    END_IF;
  305:
    nLayerStartState_bak := 305;
    g_bZFollowClose := TRUE;
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
      IF g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_HIGH.bPierEnable THEN
        nLayerStartState := 310;
      ELSIF g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_MIDDLE.bPierEnable THEN
        nLayerStartState := 330;
      ELSIF g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_LOW.bPierEnable THEN
        nLayerStartState := 360;
      END_IF;
    END_IF;
  310:(*高位穿孔*)
    nLayerStartState_bak := 310;
    g_ugas_type := g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas;
    g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas_Pressure;
    g_dair_pressure := g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas_Pressure;
    g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas_Pressure;
    g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas_Pressure;

    g_fZRelDistance := g_TechData.multilTechData[nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Height - 1.0;
    g_bZRelExecute := TRUE;
    g_bgas_enable := TRUE; 
    IF g_bFirstGas THEN(*首吹气延时:*)
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(MAX(g_nFirstGasDelayTime,g_nOpenGasDelayTimeAdd))));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE);
        g_bFirstGas := FALSE;
        nLayerStartState := 312;
      END_IF;
    ELSE
      TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nOpenGasDelayTimeAdd)));
      IF TON_FirstGasDelay.Q THEN
        TON_FirstGasDelay(IN :=FALSE); 
        nLayerStartState := 312;
      END_IF;
    END_IF;   
 312:(*等待到达高位完成*)
    nLayerStartState_bak := 312;
    g_bFirstGas := FALSE;  (*首吹气标志位复位*)
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerStartState := 318;
    END_IF;
  314:(*高位穿孔高度>=随动最高高度,探底*)
