      END_IF;
    END_IF;
    IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN
      nTimeTemp := nTimeTemp + g_nOpenGasDelayTimeAdd;
    END_IF;
    TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTimeTemp)));
    IF TON_FirstGasDelay.Q THEN
      TON_FirstGasDelay(IN :=FALSE);
      IF g_bProfileEnable AND NOT g_bProfileFollowEnable THEN(*板外切割：关随动切割*)
        nLayerStartState := 422;
      ELSE
        nLayerStartState := 420;
      END_IF;
    END_IF;

  415:
    nLayerStartState_bak := 415;
    g_ugas_type := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;
    g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_dair_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;
    g_bgas_enable := TRUE;
    IF g_bFirstGas THEN
      IF g_bChangeGasFlag THEN 
        nTimeTemp := g_nFirstGasDelayTime + g_nChangeGasDelayTime;
      ELSE
        nTimeTemp := g_nFirstGasDelayTime;
      END_IF;
    ELSE
      IF g_bChangeGasFlag THEN 
        nTimeTemp := g_nChangeGasDelayTime;
      ELSE
        nTimeTemp := g_nOpenGasDelayTimeAdd;
      END_IF;
    END_IF;
    IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN
      nTimeTemp := nTimeTemp + g_nOpenGasDelayTimeAdd;
    END_IF;
    TON_FirstGasDelay(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nTimeTemp)));
    IF TON_FirstGasDelay.Q THEN

      TON_FirstGasDelay(IN :=FALSE);

      nLayerStartState := 425;

    END_IF;

  420:(*等待切割随动到位*)
    nLayerStartState_bak := 420; 
    g_bChangeGasFlag := FALSE;   (*复位换气标志位*) 
    g_bFirstGas := FALSE;        (*复位首吹气标志位*)
    IF g_bZFollowDone THEN
      g_bZFollowExecute := FALSE;
      TON_FirstGasDelay(IN := FALSE);
      nLayerStartState := 430;
      IF g_bProcessHalCloseFollowState THEN
        nLayerStartState := 427;
      END_IF;
      bZHeightJudgeOpen := FALSE;
    END_IF;
  422:(*板外切割：等待切割到位*)
    nLayerStartState_bak := 422; 
    g_bChangeGasFlag := FALSE;   (*复位换气标志位*) 
    g_bFirstGas := FALSE;        (*复位首吹气标志位*)
    IF g_bZAbsDone THEN
      g_bZAbsExecute := FALSE;  
      TON_FirstGasDelay(IN := FALSE);
      nLayerStartState := 430;
    END_IF;
  425:  
    nLayerStartState_bak := 425; 
    g_bChangeGasFlag := FALSE;   (*复位换气标志位*) 
    g_bFirstGas := FALSE;        (*复位首吹气标志位*)
    nLayerStartState := 430; 

  427:(*引脚触发关随动切割，随动下来后，把随动关了*)
    nLayerStartState_bak := 427;
    g_bZFollowClose := TRUE;
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
      TON_FirstGasDelay(IN := FALSE);
      nLayerStartState := 430;
    END_IF;
  430:(*切割出光*)
   nLayerStartState_bak := 430;
    IF g_bFocusDone THEN(*调焦完成*)
        g_nPower := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Power));
        g_nPwmFreq := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Frequency));
        g_nPwmDuty := LREAL_TO_UINT(UINT_TO_LREAL(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_Duty));
        g_bLaserCuttingEnable := TRUE;
        IF g_bProcessHalCloseLaserState THEN(*外部M代码关光标志*)
          g_bLaserCuttingEnable := FALSE;
        END_IF;
        IF g_bLayerStartOffLaser THEN(*轮廓随动不开关标志位,直到引脚开随动将它冲掉*)
          g_bLaserCuttingEnable := FALSE;
        END_IF; 
        nLayerStartState := 440;
    END_IF;
  440:(*开启NC运动使能*)
    nLayerStartState_bak := 440;
    TON_PreCutDelay(IN:=TRUE,PT :=LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_PreCutDelay)));
    IF TON_PreCutDelay.Q THEN(*预切割延时：延时完成开始NC运动*)
      TON_PreCutDelay(IN :=FALSE);
      g_boCNCMoveDisable := FALSE;
      nLayerStartState := 500;
    END_IF;   
  500:(*切割中*)
    nLayerStartState_bak := 500;
    g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
    nLayerStartState := 500;
    g_nCurCutState :=1;
  501:(*板外切割 第二阶段 空行中*)
    nLayerStartState_bak := 501;
    g_foCuttingSpeed := g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Speed *1000.0;
    nLayerStartState := 501;
    g_nCurCutState :=0;
  600:(*和速度为0*)
    IF g_fiXYUCurrentSpeed<=0.001 THEN
      nLayerStartState := 601;
    END_IF;
  601:
    (*暂停-关光关气*)
    IF g_bDryRunEnable OR g_bDebugMode THEN
      nLayerStartState := 602;
    ELSE
      IF g_bLaserCuttingEnable THEN
        TON_PauseStopLaserDelay(IN:=TRUE,PT :=LREAL_TO_TIME(FUN_MStoS(g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.nCutting_PauseStopLaserDelay)));
        IF TON_PauseStopLaserDelay.Q THEN(*暂停关光延时*)
          TON_PauseStopLaserDelay(IN :=FALSE);
          g_bLaserCuttingEnable := FALSE;
          bCloseGasDelayEnable := TRUE;
          g_bgas_enable := FALSE;
          nLayerStartState := 602;
        END_IF;
      ELSE
        g_bgas_enable := FALSE;
        g_bLaserCuttingEnable := FALSE;
        bCloseGasDelayEnable := TRUE;
        nLayerStartState := 602;
      END_IF;
    END_IF;
  602: 
    g_bZLiftExecute := FALSE;
    IF Axis_Z.NCTOPLC.AXISSTATE = 2 THEN
      nLayerStartState := 610;
    END_IF;
  610:
    (*遇到某些不需要上抬的情况，直接进入下一个状态机，否则上抬*)
    IF g_bDryRunEnable OR bLookBackEnable OR g_bDebugMode THEN
      nLayerStartState := 620;
    ELSE
      g_bZLiftExecute := TRUE;
    END_IF;
    IF g_bZLiftingDone THEN
      g_bZLiftExecute := FALSE;
      nLayerStartState := 620;
    END_IF;
  620:(*暂停*)
    IF nLayerStartState_bak=0 THEN
      nLayerStartState := 0;
    ELSIF bLookBackEnable OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack  THEN
      nLayerStartState := 0;
      g_boCNCMoveDisable := FALSE;
      bLookBackDone := TRUE;
      g_bAutoExecuteFallBack := FALSE;
    ELSIF bCurState AND (g_bDryRunEnable OR g_bDebugMode) THEN
      nLayerStartState := 500;
      g_boCNCMoveDisable := FALSE;
    ELSIF bCurState AND nLayerStartState_bak>=400 THEN
      IF nLayerStartState_bak >=440 THEN
        bStratAfterPause := TRUE; 
      END_IF;
      nLayerStartState := 400;
      g_boCNCMoveDisable := TRUE;
    ELSIF bCurState AND nLayerStartState_bak<400 THEN
      nLayerStartState := 9;
    END_IF;
END_CASE;

CASE nLayerEndState OF
  0:(*空闲*)
    nLayerEndState_bak := 0;
    nLayerEndState := 0;
    WaitTimeOut(IN := FALSE);
  10:(*关闭CNC运动使能*)
    nLayerEndState_bak := 10;
    g_boCNCMoveDisable := TRUE;
    nLayerEndState := 100;
  100:(*关闭切割关光*)
    nLayerEndState_bak := 100;
    Timer_LayerEndStopLightTime(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nLayerEndStopLight_Time)));
    IF Timer_LayerEndStopLightTime.Q THEN
      Timer_LayerEndStopLightTime(IN := FALSE);
      g_bLaserCuttingEnable := FALSE;
      g_nCurCutState :=0;
      (*型材切割有可能会出现未开随动轮廓结束，所以执行Layer_End，如果发现不在随动状态，直接跳过关随动状态机*)
      IF Axis_Z.NCTOPLC.AxisState = 9 THEN
        nLayerEndState := 110;
      ELSE
        bCloseGasDelayEnable := TRUE;
        nLayerEndState := 200;
      END_IF;
    END_IF;
  110:(*关闭切割关气，关随动*)
    nLayerEndState_bak := 110;
    bCloseGasDelayEnable := TRUE;
    g_bZFollowExecute := FALSE;
    g_bZFollowClose := TRUE;
    IF g_bZFollowOutDone THEN
      (*如果是微连的话，不需要进入111，直接进入上抬判断*)
      IF LREAL_TO_INT(g_fMicroConnectEnableM) = 1 THEN
        nLayerEndState := 200;
        g_boClaw3UpLiftDone := TRUE;
      ELSIF g_nMachineType = 6 THEN
        nLayerEndState := 111;
      ELSIF g_nMachineType = 9 THEN
        nLayerEndState := 130;
      ELSE
        nLayerEndState := 200;
      END_IF;
      g_bZFollowClose := FALSE;
      IF g_bRealTimeCAlibrateStarting THEN
        g_bRealTimeCAlibrateStarting := FALSE;
        g_bZLiftExecute := TRUE;
        nLayerEndState := 307;
      END_IF;
    END_IF;
  111:
    nLayerEndState_bak := 111;
    g_boCNCMoveDisable := TRUE;

    IF bUpLiftFlag OR (g_dNestingDistanceToGoM = 0.0 AND g_dNestingMotionAngleM = 0.0) THEN
      IF Axis_Z.NCTOPLC.ACTPOS > (g_fLiftCoord - 1.0) THEN
        nLayerEndState := 600;
        g_boCNCMoveDisable := FALSE;
      ELSE
        nLayerEndState := 200;
      END_IF;
    ELSIF bClaw3UpLiftFlag THEN
      IF Axis_Z.NCTOPLC.ACTPOS >= (g_fLiftCoord - 1.0) THEN
        nLayerEndState := 120;
      ELSE
        g_bZRelExecute := FALSE;
        nLayerEndState := 115;
      END_IF;
    END_IF;
  115:
    nLayerEndState_bak := 115;
    g_bZRelExecute := TRUE;
    g_fZRelDistance := dUpLiftheight;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      g_boClaw3UpLiftDone := TRUE;
      nLayerEndState := 120;
    END_IF;
  120:
    nLayerEndState_bak := 120;
    g_boClaw3UpLiftDone := TRUE;

    IF bUpLiftFlag THEN
      IF Axis_Z.NCTOPLC.ACTPOS > (g_fLiftCoord - 1.0) THEN
        nLayerEndState := 600;
        g_boCNCMoveDisable := FALSE;
      ELSE
        nLayerEndState := 200;
      END_IF;
    END_IF;
  130:
    g_boCNCMoveDisable := FALSE;
    IF g_boBoendeCheckDone THEN
      g_boCNCMoveDisable := TRUE;
      nLayerEndState := 200;
    END_IF;
  200:(*判断是否蛙跳*)
    nLayerEndState_bak := 200;

    (*没有蛙跳，直接上抬*)
    IF bFrogLeapEnable AND (g_dNestingDistanceToGoM <> 0.0 OR g_dNestingMotionAngleM <> 0.0) THEN(*当下个零件剩余角度和距离都为0时，确认已经是最后一个轮廓了，不蛙跳。*)
      nLayerEndState := 210;(*执行蛙跳*)
      IF g_dNestingIsUseSideCenterM<>0.0 OR g_dNestingIsPullerM = 1.0 THEN(*下个轮廓执行分中的话，就不执行蛙跳了,下个轮廓要拉料的话也不要蛙跳*)
        nLayerEndState := 300;(*直接上抬*) 
      END_IF;
    ELSE
      nLayerEndState := 300;(*直接上抬*) 
    END_IF;
    IF bFrogLeapEnable AND g_bClaw2Aoiding THEN(*当前情况是当卡盘避让和蛙跳同时执行时，蛙跳上台而cnc未运动，Z轴重新上台到轮廓高度，确保管子不碰到切割头*)
      g_bClaw2Aoiding := FALSE;
      nLayerEndState := 300;(*直接上抬*)
    END_IF;
    (*根据不同管型，获取△上抬距离（安全距离） pipetype: 0、平面 1、圆 2、矩形 3、腰 4、椭圆 5、D型管 10、H钢 11、角钢*)
    dXCoordToCenter := ABS(g_diXMachineCoordinate - g_dBeamCenterPos);(*X轴当前坐标距离X轴中心的距离*)
    IF g_nPipeType = 1 THEN 
      IF dXCoordToCenter >= 0.5 THEN(*判断是平面孔情况的还是空间孔情况*) 
         (*如果轮廓跳转时检测到X轴不在中心位置，需要上抬保证安全*)
         dCircleLiftTemp := SQRT(g_dCircleRadius*g_dCircleRadius - dXCoordToCenter*dXCoordToCenter);
         dMaxChangeHeight := g_dCircleRadius - dCircleLiftTemp + 1.0;
      ELSE
        dMaxChangeHeight := 0.0; 
      END_IF;
    ELSIF g_nPipeType = 2 OR g_nPipeType = 11 THEN
      dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) - MIN(g_dSquareLenght,g_dSquareWidth)/2.0 + 10.0;
    ELSIF g_nPipeType = 3 OR g_nPipeType = 4 THEN  
      dMaxChangeHeight := (g_dSquareLenght-g_dSquareWidth)/2.0 + 5.0;
    ELSIF g_nPipeType = 10 THEN
      dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) + 10.0;
     ELSIF g_nPipeType = 12 THEN
       dMaxChangeHeight := SQRT(g_dBoundRectangleWidth*g_dBoundRectangleWidth/4.0 + g_dBoundRectangleheight*g_dBoundRectangleheight/4.0) - MIN(g_dBoundRectangleWidth,g_dBoundRectangleheight)/2.0 + 10.0; 
    ELSE(*对于未做蛙跳处理的管型，默认不蛙跳，比如椭圆管，腰管*) 
      dMaxChangeHeight := 0.0;
      nLayerEndState := 300;
    END_IF;

  210:(*蛙跳情况分类*)
    nLayerEndState_bak := 210;
    (*下个零件距离和角度的比值*)
    dDistanceAndAngleRealRate := g_dNestingDistanceToGoM/g_dNestingMotionAngleM;
    dDistanceAndAngleRate := 1.0/3.0;
    (*pipetype: 0、平面 1、圆 2、矩形 3、腰 4、椭圆 5、D型管 10、H钢 11、角钢*)
    IF g_nPipeType = 1 THEN   
      IF g_dNestingMotionAngleM = 0.0 THEN
          bFropLeapType := 2;(*根据X（或Y轴）和Z轴的速度比计算蛙跳上抬的高度*)
          nLayerEndState := 500; 
      ELSE 
        IF g_dNestingDistanceToGoM = 0.0 THEN
          bFropLeapType := 1;
        ELSE(*按比例来，大于比例用距离，小于比例用角度*)
          IF dDistanceAndAngleRealRate > dDistanceAndAngleRate THEN
            bFropLeapType := 2;
          ELSE
            bFropLeapType := 1;
          END_IF;
        END_IF;
        nLayerEndState := 500;  
      END_IF;
    ELSIF g_nPipeType = 2 OR g_nPipeType = 10 OR g_nPipeType = 11 THEN 
      (*判断是不是在同一面蛙跳*)
      IF g_dNestingMotionAngleM = 0.0 THEN(*蛙跳到同一面*) 
        bFropLeapType := 2;
        dMaxChangeHeight := 0.0;
        nLayerEndState := 520;(*无安全隐患，直接蛙跳*) 
      ELSE(*蛙跳到另一面*)
        IF g_dNestingDistanceToGoM = 0.0 THEN
          bFropLeapType := 1;
        ELSE(*按比例来，大于比例用距离，小于比例用角度*)
          IF dDistanceAndAngleRealRate > dDistanceAndAngleRate THEN
            bFropLeapType := 2;
          ELSE
            bFropLeapType := 1;
          END_IF; 
        END_IF ;  
        nLayerEndState := 500;
      END_IF;
    ELSIF g_nPipeType = 3 THEN (*腰管*)
      (*判断是不是在同一面蛙跳*)
      IF g_dNestingMotionAngleM = 0.0 THEN(*蛙跳到同一面*) 
        bFropLeapType := 2;
        nLayerEndState := 500;
        (*当前切割头如果在腰管的AC面的同一水平面*)
        (*IF dXCoordToCenter <= (g_dSquareLenght-g_dSquareWidth)/2.0 THEN
          dMaxChangeHeight := 0.0;
          nLayerEndState := 520; 
        END_IF;*) (*无安全隐患，直接蛙跳*) 
      ELSE(*蛙跳到另一面*)
        IF g_dNestingDistanceToGoM = 0.0 THEN
          bFropLeapType := 1;
        ELSE(*按比例来，大于比例用距离，小于比例用角度*)
          IF dDistanceAndAngleRealRate > dDistanceAndAngleRate THEN
            bFropLeapType := 2;
          ELSE
            bFropLeapType := 1;
          END_IF; 
        END_IF ;  
        nLayerEndState := 500;
      END_IF;
    ELSIF g_nPipeType = 4 THEN 
      (*判断是不是在同一面蛙跳*)
      IF g_dNestingMotionAngleM = 0.0 THEN(*蛙跳到同一面*) 
        bFropLeapType := 2;
        nLayerEndState := 500;
      ELSE(*蛙跳到另一面*)
        IF g_dNestingDistanceToGoM = 0.0 THEN
          bFropLeapType := 1;
        ELSE(*按比例来，大于比例用距离，小于比例用角度*)
          IF dDistanceAndAngleRealRate > dDistanceAndAngleRate THEN
            bFropLeapType := 2;
          ELSE
            bFropLeapType := 1;
          END_IF; 
        END_IF ;  
        nLayerEndState := 500;
      END_IF;
    END_IF;

    WaitTimeOut(IN := TRUE,PT := T#30ms);
    IF WaitTimeOut.Q THEN
      nLayerEndState := 300; (*layend触发了,但是拿不到剩余距离，延时到了之后就直接上抬*)
      g_bZRelExecute := FALSE;
      WaitTimeOut(IN := FALSE);
    END_IF;
  300:(*不蛙跳上抬*)
    nLayerEndState_bak := 300;
    IF g_dNestingDistanceToGoM=0.0 AND g_dNestingMotionAngleM=0.0 THEN (*判断下个轮廓的移动距离和角度同时为0即为程序结束直接上抬到最高点*)
      g_bZLiftExecute := TRUE;
      nLayerEndState := 307;
    ELSIF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight + dMaxChangeHeight) <= g_fLiftCoord THEN
      (*dUpLiftheight:轮廓间上抬高度  dMaxChangeHeight：△上抬距离（安全距离）*)
       g_fZRelDistance := dUpLiftheight + dMaxChangeHeight;
        nLayerEndState := 305;
    ELSE
      g_bZLiftExecute := TRUE;
      nLayerEndState := 307;
    END_IF; 
  305:
    g_bZRelExecute := TRUE;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      nLayerEndState := 310;
    END_IF;
  307:
    nLayerEndState_bak := 307;
    IF g_bZLiftingDone THEN
      nLayerEndState := 310;
      g_bZLiftExecute := FALSE;
    END_IF;
  310:(*不蛙跳：开启CNC运动使能*)
    nLayerEndState_bak := 310; 
    g_boCNCMoveDisable := FALSE;
    nLayerEndState := 600; 


  500:(*蛙跳前：计算避让上抬安全高度*) 
    nLayerEndState_bak := 500;

    IF g_nPipeType = 1 THEN 
      dXCoordToCenter := ABS(g_diXMachineCoordinate - g_dBeamCenterPos);(*X轴当前坐标距离X轴中心的距离*)
      IF dXCoordToCenter >= 0.5 THEN(*判断是平面孔情况的还是空间孔情况*) 
         (*如果轮廓跳转时检测到X轴不在中心位置，需要上抬保证安全*)
         dCircleLiftTemp := SQRT(g_dCircleRadius*g_dCircleRadius - dXCoordToCenter*dXCoordToCenter);
         dMaxChangeHeight := g_dCircleRadius - dCircleLiftTemp;
      ELSE
        dMaxChangeHeight := 0.0; 
      END_IF;
    ELSIF g_nPipeType = 2 OR g_nPipeType = 11 THEN
      dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) - MIN(g_dSquareLenght,g_dSquareWidth)/2.0;
    ELSIF g_nPipeType = 3 OR g_nPipeType = 4 THEN  
      dMaxChangeHeight := (g_dSquareLenght-g_dSquareWidth)/2.0;
    ELSIF g_nPipeType = 10 THEN
      dMaxChangeHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0); 
    END_IF;
    nLayerEndState := 520; 
  520:(*蛙跳 ：根据U或者X或者Y轴速度于Z速度的比值计算可上抬高度*) 
    nLayerEndState_bak := 520;  
    IF bFropLeapType = 1 THEN(*U/Z*)(*根据U轴和Z轴的速度比计算蛙跳上抬的高度*)
      dG00Vel := g_dUG00Vel; 
      dCalUpliftHight := 0.5*g_dNestingMotionAngleM*g_fZAxisVel/dG00Vel;(*同比例下Z轴能上抬的高度*)
    ELSIF bFropLeapType = 2 THEN(*X/Z*)(*根据X（或Y轴）和Z轴的速度比计算蛙跳上抬的高度*)
      dG00Vel := MIN(g_dXG00Vel,g_dYG00Vel); 
      dCalUpliftHight := 0.5*g_dNestingDistanceToGoM*g_fZAxisVel/dG00Vel;(*同比例下Z轴能上抬的高度*)
    END_IF;  
    (*对计算出来的高度进行异常过滤*)
    IF dCalUpliftHight > dUpLiftheight OR dCalUpliftHight <= 0.0 THEN (*如果计算出来的上抬高度,大于设置上抬高度则用设置上抬高度*)
       dCalUpliftHight := dUpLiftheight;
    END_IF; 
    dFropLeapLiftUpHeight := dMaxChangeHeight + dCalUpliftHight;
    nLayerEndState := 525;  
  525:(*蛙跳：蛙跳开启CNC运动使能*) 
    nLayerEndState_bak := 525;
    IF Axis_Z.NCTOPLC.ACTPOS  >= g_fLiftCoord THEN
      g_fZRelDistance := 0.0;  
    ELSIF Axis_Z.NCTOPLC.ACTPOS  < g_fLiftCoord THEN
      IF Axis_Z.NCTOPLC.ACTPOS + dFropLeapLiftUpHeight >= g_fLiftCoord THEN
        g_fZRelDistance := g_fLiftCoord - Axis_Z.NCTOPLC.ACTPOS;
      ELSE
        g_fZRelDistance := dFropLeapLiftUpHeight;
      END_IF;
    END_IF;
    dZSetPosTemp := Axis_Z.NCTOPLC.ACTPOS;
    g_bZRelExecute := TRUE;
    nLayerEndState := 530; 
  530:(*蛙跳：蛙跳上抬*)(* 边上抬边CNC移动*)
    nLayerEndState_bak := 530;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      g_boCNCMoveDisable := FALSE; 
      nLayerEndState := 540;
    ELSIF Axis_Z.NCTOPLC.ACTPOS - dZSetPosTemp >= dMaxChangeHeight THEN(*高度在上抬到大于安全高度的位置，就可以移动CNC轴进行蛙跳了*)
      g_boCNCMoveDisable := FALSE; 
      nLayerEndState := 535;
    END_IF;  
  535:(*蛙跳上抬中*)
    nLayerEndState_bak := 535;
    IF g_bZRelDone THEN
      g_bZRelExecute := FALSE;
      g_boCNCMoveDisable := FALSE;
      nLayerEndState := 540;
    END_IF; 
  540:(*蛙跳上抬完成，获取CNC传来的剩余角度或剩余数据，等待下落条件满足*)
    nLayerEndState_bak := 540;
    IF bFropLeapType=1 THEN
      dResidueTemp := g_diMotionAngle;
    ELSIF bFropLeapType=2 THEN
      dResidueTemp := g_diMotionDistance;
    END_IF; 
    IF dResidueTemp = 0.0 THEN (*如果获取的数据为零，可能还未传过来，延时等待一下*)
      IF g_bClaw2Aoiding OR g_bProcessEndStopFlag THEN(*由别处将触发打断蛙跳时，将直接上抬：卡盘避让，计件暂停报警*)
        IF Axis_Z.NCTOPLC.ACTPOS >= dUpLiftheight THEN
          nLayerEndState := 600;
        ELSE 
          nLayerEndState := 200;
        END_IF;
        Ton_wait1(IN :=FALSE);
      ELSIF g_doMCodeEnable<>0.0 THEN (*如果有M代码正在执行中，那么等待M代码的enable为0，否则会拿不到CNC传来的剩余角度或剩余数据*)
        Ton_wait1(IN :=FALSE);
      ELSE
        Ton_wait1(IN := TRUE,PT := T#100ms); 
        IF Ton_wait1.Q THEN
          Ton_wait1(IN :=FALSE);
          nLayerEndState := 545;
        END_IF;
      END_IF;
    ELSE
       Ton_wait1(IN :=FALSE);
       nLayerEndState := 545;
    END_IF; 
  545:(*等待满足蛙跳随动下落条件*)
    nLayerEndState_bak := 545;
    IF g_dNestingDistanceToGoM = 0.0 AND g_dNestingMotionAngleM <> 0.0 THEN
      g_doLeapfrogDownType := 1.0;
      (*情况1:当实际剩余角度小于提前下落角度时，开启随动下落，提前下落角度不能太大，所以需要限制*)
      IF (g_diMotionAngle <= MIN(dFrogLeapPreAngle,15.0)) THEN 
        nLayerEndState := 580;
      END_IF;  
    ELSIF g_dNestingDistanceToGoM <> 0.0 AND g_dNestingMotionAngleM = 0.0 THEN
      g_doLeapfrogDownType := 2.0;
      (*情况2：当实际剩余距离小于蛙跳提前下落距离时，开始随动下落，如果蛙跳提前下落距离大于下个零件剩余距离的一半，则取下个零件剩余距离的一半*)
      IF g_diMotionDistance <= MIN(dFrogLeapPreDistance,0.5*g_dNestingDistanceToGoM) THEN 
        nLayerEndState := 580;
      END_IF; 
    ELSE
      g_doLeapfrogDownType := 3.0;
      (*情况3：同时满足1、2条件*)
      (*1 、当实际剩余角度小于提前下落角度时，开启随动下落，提前下落角度不能太大，所以需要限制*)
      (*2 、当实际剩余距离小于蛙跳提前下落距离时，开始随动下落，如果蛙跳提前下落距离大于下个零件剩余距离的一半，则取下个零件剩余距离的一半*)
      IF (g_diMotionAngle <= MIN(dFrogLeapPreAngle,15.0)) AND (g_diMotionDistance <= MIN(dFrogLeapPreDistance,0.5*g_dNestingDistanceToGoM)) THEN 
        nLayerEndState := 580;
      END_IF;
    END_IF; 

  580:(*蛙跳随动下落*)

    nLayerEndState_bak := 580;

    IF g_TechData.multilTechData[g_nToolNum-1].nPiercing_Type=0 THEN

      nLayerEndState := 582;

    ELSIF g_TechData.multilTechData[g_nToolNum-1].nPiercing_Type=1 THEN

      nLayerEndState := 584;

    ELSE

      nLayerEndState := 587;

    END_IF;

  582:  (*直接切割高度>=随动最高高度，蛙跳到1mm*)

    nLayerEndState_bak := 582;
    IF g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height <= g_dZFollowMaxHeight THEN

      g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Height;  

    ELSE

      g_fZFollowHeight := 1.0;

    END_IF;      

    g_bZFollowExecute := TRUE;



    g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.nCutting_Gas;

    g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;

    g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;

    g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;

    g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.fCutting_Gas_Pressure;

    g_bgas_enable := TRUE;

    TON_FrogLeapOpenGas(IN := TRUE,PT := T#20s);  (*蛙跳出气计时*)

    IF g_bZFollowDone THEN

      nLayerEndState := 588;

      g_bZFollowExecute := FALSE;
      bZHeightJudgeOpen := FALSE;
    END_IF;

  584:

    nLayerEndState_bak := 584;

    IF g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height <= g_dZFollowMaxHeight THEN 

      g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height;

    ELSE

      g_fZFollowHeight := 1.0;

    END_IF;

    g_bZFollowExecute := TRUE;

    g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.nNormal_Piercing_Gas;

    g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;

    g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;

    g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;

    g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Gas_Pressure;

    g_bgas_enable := TRUE;  (*蛙跳下落开始出气*)

    TON_FrogLeapOpenGas(IN := TRUE,PT := T#20s);  (*蛙跳出气计时*)

    IF g_bZFollowDone THEN

      nLayerEndState := 588;

      g_bZFollowExecute := FALSE;
      bZHeightJudgeOpen := FALSE;
    END_IF;

  587:

    nLayerEndState_bak := 587;

    (*蛙跳下落位置*)

      IF g_TechData.multilTechData[g_nToolNum-1].nPiercing_Type=2 THEN (*渐进穿孔*)

        IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.bBurstingHole_Enable THEN (*是否爆孔*)

          IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height <= g_dZFollowMaxHeight THEN (*爆孔高度<随动最高高度，否则需要探底后再到爆孔位置*)

            g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height;

            ELSE

              g_fZFollowHeight := 1.0;

            END_IF; 

        ELSE

          g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Height;

        END_IF;

      ELSIF g_TechData.multilTechData[g_nToolNum-1].nPiercing_Type=3 THEN (*多级穿孔*)

        IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.bPierEnable THEN

          IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Height <= g_dZFollowMaxHeight THEN

            g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Height;

          ELSE

            g_fZFollowHeight := 1.0;

          END_IF; 

        ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.bPierEnable THEN

          IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Height <= g_dZFollowMaxHeight THEN

            g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Height;

          ELSE

            g_fZFollowHeight := 1.0;

          END_IF; 

        ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.bPierEnable THEN

          IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.Mulitil_Piercing_Height <= g_dZFollowMaxHeight THEN

            g_fZFollowHeight := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.Mulitil_Piercing_Height;

          ELSE

            g_fZFollowHeight := 1.0;

          END_IF;

        END_IF;

      END_IF;    

    g_bZFollowExecute := TRUE;

    IF g_bZFollowDone THEN

      nLayerEndState := 588;

      g_bZFollowExecute := FALSE;
      bZHeightJudgeOpen := FALSE;
    END_IF;



    (*蛙跳下落出气*)

    IF g_TechData.multilTechData[g_nToolNum-1].nPiercing_Type=2 THEN (*渐进穿孔*)

        IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.bBurstingHole_Enable THEN (*是否爆孔*)

          g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_gas;

          g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;

          g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;

          g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;

          g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fBurstingHole_gas_pressure;

        ELSE

          g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nMove_Piercing_Gas;

          g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;

          g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;

          g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;

          g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.fMove_Piercing_Gas_Pressure;

        END_IF;

    ELSIF g_TechData.multilTechData[g_nToolNum-1].nPiercing_Type=3 THEN (*多级穿孔*)

        IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.bPierEnable THEN

          g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas;

          g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas_Pressure;

          g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas_Pressure;

          g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas_Pressure;

          g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Gas_Pressure;

        ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.bPierEnable THEN

          g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Gas;

          g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Gas_Pressure;

          g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Gas_Pressure;

          g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Gas_Pressure;

          g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Gas_Pressure;

        ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.bPierEnable THEN

          g_ugas_type := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.Mulitil_Piercing_Gas;

          g_dmaster_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.Mulitil_Piercing_Gas_Pressure;

          g_dair_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.Mulitil_Piercing_Gas_Pressure;

          g_doxygen_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.Mulitil_Piercing_Gas_Pressure;

          g_dnitogen_pressure := g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.Mulitil_Piercing_Gas_Pressure;

        END_IF;

    END_IF;

    g_bgas_enable := TRUE;

    TON_FrogLeapOpenGas(IN := TRUE,PT := T#20s);  (*蛙跳出气计时*)
  588:
    nLayerEndState_bak := 588;
    TON_CloseGasDelay(IN :=FALSE);
    TON_FirstGasDelay(IN := TRUE);
    IF (g_niMotionType=1 AND g_diMotionDistance<=0.05 AND g_diMotionAngle<=0.05) OR g_niMotionType<>1 THEN
        g_bZFollowClose := TRUE;
    END_IF;
    IF g_bZFollowOutDone THEN
      nLayerEndState := 600;
      g_bZFollowClose := FALSE;
    END_IF;
  600:(*LayerEnd完成*)(*用于layerStart中等其结束防止异常结束,建议采集高电平*)
    nLayerEndState_bak := 600;
    g_boLayerEndDone := TRUE;
    g_boClaw3UpLiftDone := TRUE;
    g_dNestingDistanceToGoM := 0.0;
    g_dNestingMotionAngleM := 0.0;
    g_dNestingIsUseSideCenterM := 0.0;
    nLayerEndState := 601;
  601:
    nLayerEndState_bak := 601;
    nLayerEndState := 601;
  700:(*暂停*)
    g_bZLiftExecute := FALSE;
    IF Axis_Z.NCTOPLC.AXISSTATE = 2 THEN
      nLayerEndState := 710;
    END_IF;
  710:
    IF g_bDryRunEnable OR bLookBackEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack  THEN
      nLayerEndState := 720;
    ELSE
      g_bZLiftExecute := TRUE;
    END_IF;
    IF g_bZLiftingDone THEN
      g_bZLiftExecute := FALSE;
      nLayerEndState := 720;
    END_IF;
  720:
    IF nLayerEndState_bak=0 THEN
      nLayerEndState := 0;
    ELSIF bLookBackEnable  OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack  THEN
      g_boCNCMoveDisable := FALSE;
      nLayerEndState := 0;
      bLookBackDone := TRUE;
      g_boLayerEndDone := TRUE;
      g_bAutoExecuteFallBack := FALSE;
    ELSIF bCurState THEN
      IF g_bDryRunEnable OR g_bDebugMode THEN
        g_boCNCMoveDisable := FALSE;
        nLayerEndState := 600;
      ELSIF g_nMachineType = 6 THEN
        nLayerEndState := 111;
        g_boCNCMoveDisable := FALSE;
      ELSIF bFrogLeapEnable AND (g_dNestingDistanceToGoM <> 0.0 OR g_dNestingMotionAngleM <> 0.0) THEN
       nLayerEndState := 540;
       g_boCNCMoveDisable := FALSE;
      ELSIF nLayerEndState_bak=601 THEN
        nLayerEndState := 601;
        g_boCNCMoveDisable := FALSE;
      ELSE
       nLayerEndState := 310;
      END_IF;
    END_IF;
END_CASE;
IF g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.bCuttingLongBlows AND (nLayerStartState <> 0 OR nLayerEndState <> 0) AND g_nPlcState = 1  AND 
  NOT (g_bDryRunEnable OR g_bDebugMode OR g_bFallBackStatusFb OR g_bAutoExecuteFallBack OR g_bForwardStatusFb) THEN
  g_bgas_enable := TRUE;
ELSIF nLayerStartState = 0 AND nLayerEndState = 0 AND NOT g_bManualOpenGas  THEN 
  g_bgas_enable := FALSE;
END_IF;
Rtring_ZProtect(CLK := bZHeightJudgeOpen);(*高度再判断一个随动误差*)
Ftring_ZProtect(CLK := bZHeightJudgeOpen);
IF Ftring_ZProtect.Q THEN
  nZProtectstate := 0;
  g_bZHeightJudgeOpen := FALSE;
END_IF;
IF Rtring_ZProtect.Q THEN
   IF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=0 THEN (*直接切割，卡盘中心高度-G00Z高度 - 切割高度*)
      nZProtectstate := 20;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=1 THEN(*穿孔，卡盘中心高度-G00Z高度 - 穿孔高度*)
      nZProtectstate := 100;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=2 THEN
      nZProtectstate := 200;
    ELSIF g_TechData.multilTechData[nToolNum-1].nPiercing_Type=3 THEN
      nZProtectstate := 300;
    END_IF;
    IF g_bLayerStartOffLaser THEN(*不开光切割，穿孔就跳过了*)
      nZProtectstate := 20;
    END_IF;
END_IF;
IF NOT g_bFollowprotectOPen THEN
  nZProtectstate := 0;
END_IF;
CASE nZProtectstate OF
  0:
    nZProtectstate := 0;
  20:
    dDecelerationdistance := ABS (FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
     IF g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height <= g_dZFollowMaxHeight THEN (*直接切割高度小于随动最大高度，直接到切割高度*)  
        IF ABS(g_fZCoordinate) + dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[nToolNum-1].DIRECUT_CUTTING.fCutting_Height - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
      ELSE
        IF ABS(g_fZCoordinate)+ dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
     END_IF;
  100:
    dDecelerationdistance := ABS(FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
    IF g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height <= g_dZFollowMaxHeight THEN (*普通穿孔高度<随动最高高度,直接随动到位*)
      IF ABS(g_fZCoordinate)+ dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].NORMAL_CUTTING.fNormal_Piercing_Height - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    ELSE
       IF ABS(g_fZCoordinate)+ dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    END_IF;
  200:(*渐进穿孔*)
  dDecelerationdistance := ABS(FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
      IF g_TechData.multilTechData[nToolNum-1].PROGRESS_CUTTING.bBurstingHole_Enable THEN
        IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height <= g_dZFollowMaxHeight THEN (*爆孔高度<随动最高高度,直接随动到爆孔位置*)
          IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height - g_dZHeightJudgeError THEN
            g_bZHeightJudgeOpen := TRUE;
            nZProtectstate := 0;
            g_bZFollowClose :=TRUE;
            g_bgas_enable := FALSE;
            g_bZFollowExecute :=FALSE;
          END_IF;
        ELSE
           IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
            g_bZHeightJudgeOpen := TRUE;
            nZProtectstate := 0;
            g_bZFollowClose :=TRUE;
            g_bgas_enable := FALSE;
            g_bZFollowExecute :=FALSE;
          END_IF;
        END_IF;
      ELSE
        IF g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height <= g_dZFollowMaxHeight THEN (*爆孔高度<随动最高高度,直接随动到爆孔位置*)
          IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].PROGRESS_CUTTING.nBurstingHole_Height - g_dZHeightJudgeError THEN
            g_bZHeightJudgeOpen := TRUE;
            nZProtectstate := 0;
            g_bZFollowClose :=TRUE;
            g_bgas_enable := FALSE;
            g_bZFollowExecute :=FALSE;
          END_IF;
        ELSE
           IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
            g_bZHeightJudgeOpen := TRUE;
            nZProtectstate := 0;
            g_bZFollowClose :=TRUE;
            g_bgas_enable := FALSE;
            g_bZFollowExecute :=FALSE;
          END_IF;
        END_IF;
      END_IF;
  300:(*多级穿孔*)
     IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.bPierEnable THEN
      nZProtectstate := 314;
    ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.bPierEnable THEN
      nZProtectstate := 334;
    ELSIF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_LOW.bPierEnable THEN
      nZProtectstate := 365;
    END_IF; 
  314:
  dDecelerationdistance := ABS(FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
    IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Height <= g_dZFollowMaxHeight THEN
        IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_HIGH.Mulitil_Piercing_Height - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    ELSE
       IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    END_IF;
  334:
  dDecelerationdistance := ABS(FUN_DISTANCECALC(0.0,g_fZVelocity,g_dZAxisAcceleration,g_dRunCycleNum));
    IF g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Height <= g_dZFollowMaxHeight THEN
      IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - g_TechData.multilTechData[g_nToolNum-1].MULTIL_PIERCING_MIDDLE.Mulitil_Piercing_Height - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    ELSE
        IF ABS(g_fZCoordinate)+dDecelerationdistance >= ABS(g_dChuckCenterInZpos) - ABS(g_fiZG00Height) - 1.0 - g_dZHeightJudgeError THEN
          g_bZHeightJudgeOpen := TRUE;
          nZProtectstate := 0;
          g_bZFollowClose :=TRUE;
          g_bgas_enable := FALSE;
          g_bZFollowExecute :=FALSE;
        END_IF;
    END_IF;
END_CASE;
(*判断当前高度是否大于卡盘中心-当前管面的高度*)
IF g_bZHeightJudgeOpen AND Axis_Z.NcToPlc.AXISSTATE = 9 AND g_bFollowprotectOPen THEN
  g_Alarm.alarmArray[390] := 1118;
END_IF;
(*拐角*)
IF RTrigger_Corner_in.Q THEN
  g_bLaserOnCornerM := FALSE;
  dPressure_note := g_dmaster_pressure;
  nPower_note := g_nPower;
  dAirPressure_note := g_dair_pressure;
  dOxygenPressure_note := g_doxygen_pressure;
  dNirtogenPressure_note := g_dnitogen_pressure;
  nPwmFreq_note := g_nPwmFreq;
  nPwmDuty_note := g_nPwmDuty;
  g_dmaster_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
  g_dair_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
  g_doxygen_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
  g_dnitogen_pressure := g_TechData.multilTechData[nToolNum-1].CornerCompen.dPressure;
  g_nPower := DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nPower);
  g_nPwmFreq := DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nHz);
  g_nPwmDuty :=DINT_TO_UINT(g_TechData.multilTechData[nToolNum-1].CornerCompen.nDuty);
END_IF;
IF  RTrigger_Corner_out.Q THEN
  g_bLaserOutCornerM := FALSE;
  g_dmaster_pressure := dPressure_note;
  g_nPower := nPower_note;
  g_dair_pressure := dAirPressure_note;
  g_doxygen_pressure := dOxygenPressure_note;
  g_dnitogen_pressure := dNirtogenPressure_note;
  g_nPwmFreq := nPwmFreq_note;
  g_nPwmDuty := nPwmDuty_note;
END_IF;

(*切割过程中随动跟随误差超过5,20ms报警*)
IF nLayerStartState = 500 AND ABS(g_fZFollowHeight - g_fZAxisHeight) > 5.0 AND Axis_Z.NCTOPLC.AXISSTATE = 9 AND g_ZFollowIn.DONE THEN
    TonFollowPosError(IN := TRUE,PT := T#20ms);
    IF TonFollowPosError.Q THEN
      TonFollowPosError(IN := FALSE);
      g_bFollowPosErrorAlarm := TRUE;
    END_IF;
ELSE
   TonFollowPosError(IN := FALSE);
  g_bFollowPosErrorAlarm := FALSE;
END_IF;






IF g_bPlcPauseBuffer AND nLayerStartState <> 0 THEN
  g_boCNCMoveDisable := TRUE;
  TON_NormalPiercingTime(IN := FALSE);
  TON_BurstingTime(IN := FALSE);
  Timer_Multil_High(IN := FALSE);
  Timer_Multil_Middle(IN := FALSE);
  Timer_Multil_Low(IN := FALSE);
  g_bZFollowExecute := FALSE;
  g_bZFollowClose := FALSE;
  g_bZRelExecute := FALSE;
  g_bZAbsExecute := FALSE;(*?*)
  g_fZAbsVelocity := 0.0;
  TON_PreCutDelay(IN :=FALSE);(*预切割延时定时器*)
 (* TON_PauseStopLaserDelay(IN :=FALSE);暂停关光延时*)
  TON_FirstGasDelay(IN :=FALSE);(*首点吹气延时定时器*)
  TON_ChangeGasDelay(IN :=FALSE);(*换气延时定时器*)
  TON_OpenGasDelay(IN :=FALSE);(*开气延时定时器*)
  TON_FrogLeapOpenGas(In := FALSE); (*蛙跳出气计时器*)
  TON_StopLightBlow(IN :=FALSE);(*停光吹气延时*)
  IF nLayerStartState < 600 THEN
    nLayerStartState := 600;
    TON_CloseGasDelay(IN :=FALSE);(*关气延时定时器*)
    bCloseGasDelayEnable := FALSE;
    g_ZMoveStop.EXECUTE := FALSE;
  END_IF;
  Ton_KernelWaitTime(IN := FALSE);
END_IF;

IF g_bPlcPauseBuffer AND nLayerEndState <> 0 THEN
  g_boCNCMoveDisable := TRUE;
  g_bLaserCuttingEnable := FALSE;
  g_bgas_enable := FALSE;
  g_bZFollowExecute := FALSE;
  g_bZFollowClose := FALSE;
  g_bZRelExecute := FALSE;
  g_fZRelVelocity := 0.0;
  g_bZAbsExecute := FALSE;
  g_fZAbsVelocity := 0.0;
  TON_CloseGasDelay(IN :=FALSE);(*关气延时定时器*)
  TON_FirstGasDelay(IN := FALSE);
  TON_FrogLeapOpenGas(In := FALSE); (*蛙跳出气计时器*)
  bCloseGasDelayEnable := FALSE;
  IF nLayerEndState < 700 THEN
    nLayerEndState := 700;
    g_ZMoveStop.EXECUTE := FALSE;
  END_IF;
END_IF;



IF g_bPlcResetBuffer THEN
  nLayerStartState := 0;
  nLayerEndState := 0;
  TON_NormalPiercingTime(IN := FALSE);
  TON_BurstingTime(IN := FALSE);
  Timer_Multil_High(IN := FALSE);
  Timer_Multil_Middle(IN := FALSE);
  Timer_Multil_Low(IN := FALSE);
  g_boLayerEndDone := TRUE;
  g_bLaserCuttingEnable := FALSE;
  g_bgas_enable := FALSE;
  g_bZFollowExecute := FALSE;
  g_bZFollowClose := FALSE;
  g_ZMoveStop.EXECUTE := FALSE;
  g_bZRelExecute := FALSE;
  g_fZRelVelocity := 0.0;
  g_bZAbsExecute := FALSE;(*?*)
  g_fZAbsVelocity := 0.0;
  g_boCNCMoveDisable := FALSE;
  g_bZLiftExecute := FALSE;
  bLookBackDone := FALSE;
  TON_PreCutDelay(IN :=FALSE);(*预切割延时定时器*)
  TON_PauseStopLaserDelay(IN :=FALSE);(*暂停关光延时*)
  TON_FirstGasDelay(IN :=FALSE);(*首点吹气延时定时器*)
  TON_ChangeGasDelay(IN :=FALSE);(*换气延时定时器*)
  g_bChangeGasFlag := FALSE;
  TON_OpenGasDelay(IN :=FALSE);(*开气延时定时器*)
  TON_CloseGasDelay(IN :=FALSE);(*关气延时定时器*)
  TON_FrogLeapOpenGas(In := FALSE); (*蛙跳出气计时器*)
  bCloseGasDelayEnable := FALSE;
  bUpLiftFlag := FALSE;
  bClaw3UpLiftFlag := FALSE;
  g_boClaw3UpLiftDone := FALSE;
  g_bProfileEnable := FALSE;
  g_bProfileLaserEnable := FALSE;
  g_bProfileFollowEnable := FALSE;(*板外切割关随动*)
  g_bFocusEnable := FALSE;
  g_bFProgressFocusAbs := FALSE;
  g_bFirstGas := FALSE;        (*复位首吹气标志位*)
  g_bProcessHalCloseFollowState:= FALSE;(*引脚关随动标志位*)
  g_bProcessHalCloseLaserState:=FALSE;(*引脚关关光标志位*)
  g_bProcessHalOpenLaserState:=FALSE;(*引脚开光标志位*)
  TonFlyCloseLightDelay(IN := FALSE);
  TonFlyOpenLightDelay(IN := FALSE);
  bZHeightJudgeOpen := FALSE;
  nZProtectstate := 0;
  g_bZHeightJudgeOpen := FALSE;
  Ton_KernelWaitTime(IN := FALSE);
  g_bForwardStatusFb := FALSE;
  g_bFallBackStatusFb := FALSE;
  g_bFollowPosErrorAlarm := FALSE;
END_IF;

IF g_bPlcStartBuffer THEN
  bCurState := TRUE;
END_IF;
IF g_bPlcPauseBuffer THEN
  bCurState := FALSE;
END_IF;





g_noTest1 := nLayerStartState;
g_noTest2 := nLayerEndState;
g_nLayerStart := nLayerStartState;
g_nLayerEnd := nLayerEndState;
g_doNestingIsUseSideCenter :=g_dNestingIsUseSideCenterM;
